package jo.orbitfarm.advisor.report;
import com.fasterxml.jackson.databind.ObjectMapper;import jo.orbitfarm.advisor.advice.AdviceResponse;import jo.orbitfarm.advisor.api.ApiException;import jo.orbitfarm.advisor.decision.DecisionRecordEntity;import jo.orbitfarm.advisor.decision.DecisionRecordRepository;import jo.orbitfarm.advisor.farm.FarmResponse;import jo.orbitfarm.advisor.farm.FarmService;import jo.orbitfarm.advisor.subscription.SubscriptionService;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;
@Service public class ReportService{
 private final DecisionRecordRepository decisions;private final FarmService farms;private final ObjectMapper mapper;private final SubscriptionService subscriptions;
 public ReportService(DecisionRecordRepository decisions,FarmService farms,ObjectMapper mapper,SubscriptionService subscriptions){this.decisions=decisions;this.farms=farms;this.mapper=mapper;this.subscriptions=subscriptions;}
 @Transactional(readOnly=true)public ReportResponse get(Long farmerId,Long farmId,Long decisionId){if(!subscriptions.effectivePlan(farmerId).reports())throw new ApiException(HttpStatus.FORBIDDEN,"PLAN_FEATURE_REQUIRED","التقارير متاحة ضمن الخطط المدفوعة.");FarmResponse farm=farms.get(farmId,farmerId);DecisionRecordEntity record=decisions.findById(decisionId).filter(d->d.getFarmId().equals(farmId)).orElseThrow(()->ApiException.notFound("Decision"));try{AdviceResponse advice=mapper.readValue(record.getResponseJson(),AdviceResponse.class);return new ReportResponse(Instant.now(),"هذا التقرير يعكس البيانات المحفوظة وقت إنشاء التوصية. تحقق من المصدر والتاريخ قبل استخدامه.",farm,advice);}catch(Exception e){throw new IllegalStateException("Stored advice report is invalid",e);}}
 public record ReportResponse(Instant generatedAt,String note,FarmResponse farm,AdviceResponse advice){}
}
